export declare const schema = "#graphql\n  scalar DateTime\n  scalar BigInt\n\n  type Query {\n    # Health check\n    health: HealthCheck!\n\n    # Tokens\n    token(address: String!): Token\n    tokens(\n      limit: Int = 20\n      offset: Int = 0\n      orderBy: TokenOrderBy = CREATED_AT_DESC\n      search: String\n    ): TokenConnection!\n    trendingTokens(limit: Int = 10): [Token!]!\n\n    # Pools\n    pool(address: String!): Pool\n    pools(limit: Int = 20, offset: Int = 0): PoolConnection!\n\n    # Users\n    user(address: String!): User\n\n    # Leaderboard (optimized with cache)\n    leaderboard(\n      type: LeaderboardType = TRADERS\n      limit: Int = 100\n      timeframe: LeaderboardTimeframe = DAY\n    ): [LeaderboardEntry!]!\n\n    # Transactions\n    transactions(\n      address: String\n      tokenAddress: String\n      type: TransactionType\n      limit: Int = 20\n      offset: Int = 0\n    ): TransactionConnection!\n\n    # Stats\n    globalStats: GlobalStats!\n  }\n\n  type Mutation {\n    # Sync a token from blockchain to database\n    syncToken(tokenAddress: String!): Token!\n  }\n\n  type HealthCheck {\n    status: String!\n    timestamp: DateTime!\n    version: String!\n    database: Boolean!\n    cache: CacheStatus!\n  }\n\n  type CacheStatus {\n    available: Boolean!\n    type: String!\n  }\n\n  type Token {\n    id: ID!\n    address: String!\n    creator: String!\n    name: String!\n    symbol: String!\n    decimals: Int!\n    totalSupply: String!\n    metadataUri: String!\n    imageUrl: String\n    logoUrl: String # Alias for imageUrl (frontend compatibility)\n    description: String\n\n    # Bonding curve\n    bondingCurve: String! # Alias for address (frontend compatibility)\n    circulatingSupply: String!\n    xlmReserve: String!\n    graduated: Boolean!\n    xlmRaised: String!\n    initialPrice: String # Initial bonding curve price\n\n    # Metrics\n    marketCap: String\n    currentPrice: String\n    priceChange24h: Float\n    volume24h: String!\n    volume7d: String!\n    holders: Int!\n    holders24h: Int # Holders in last 24h\n    holdersChange24h: Float # Percentage change in holders\n\n    # Social links (optional)\n    website: String\n    twitter: String\n    telegram: String\n    discord: String\n\n    # Timestamps\n    createdAt: DateTime!\n    updatedAt: DateTime!\n\n    # Relations (will use DataLoaders)\n    creatorUser: User\n    pools: [Pool!]!\n  }\n\n  type Pool {\n    id: ID!\n    address: String!\n    token0Address: String!\n    token1Address: String!\n    reserve0: String!\n    reserve1: String!\n    totalSupply: String!\n    liquidity: String! # Alias for totalSupply (frontend compatibility)\n\n    # Metrics\n    tvl: String\n    volume24h: String!\n    volume7d: String!\n    volumeChange24h: Float # Volume change percentage\n    apr: Float\n    apy: Float # Alias for apr (frontend compatibility)\n    fee: String # Pool fee percentage\n\n    createdAt: DateTime!\n    updatedAt: DateTime!\n\n    # Relations (will use DataLoaders)\n    token0: Token!\n    token1: Token!\n  }\n\n  type User {\n    id: ID!\n    address: String!\n\n    # Gamification\n    points: Int!\n    level: Int!\n    referrals: Int!\n\n    # Stats\n    tokensCreatedCount: Int!\n    totalVolumeTraded: String!\n    totalLiquidityProvided: String!\n\n    # Relations\n    tokensCreated: [Token!]!\n    achievements: [Achievement!]!\n\n    createdAt: DateTime!\n  }\n\n  type Achievement {\n    id: ID!\n    achievementId: String!\n    name: String!\n    description: String!\n    imageUrl: String!\n    progress: Int!\n    maxProgress: Int!\n    completed: Boolean!\n    unlockedAt: DateTime\n  }\n\n  type Transaction {\n    id: ID!\n    hash: String!\n    type: TransactionType!\n    from: String!\n    to: String\n    tokenAddress: String\n    amount: String\n    status: TransactionStatus!\n    timestamp: DateTime!\n\n    # Relations\n    token: Token\n    user: User\n  }\n\n  type LeaderboardEntry {\n    rank: Int!\n    address: String!\n    user: User!\n\n    # Metrics (depende del tipo de leaderboard)\n    volume24h: String!\n    trades24h: Int!\n    profitLoss24h: String!\n\n    # Para CREATORS\n    tokensCreated: Int\n    totalVolumeGenerated: String\n\n    # Para LIQUIDITY_PROVIDERS\n    totalLiquidity: String\n    feesEarned24h: String\n\n    # Cambios\n    volumeChange24h: Float\n    rankChange24h: Int\n  }\n\n  type GlobalStats {\n    totalTokens: Int!\n    totalPools: Int!\n    totalUsers: Int!\n    totalVolume24h: String!\n    totalTVL: String!\n  }\n\n  # Pagination types\n  type TokenConnection {\n    edges: [TokenEdge!]!\n    pageInfo: PageInfo!\n    totalCount: Int!\n  }\n\n  type TokenEdge {\n    cursor: String!\n    node: Token!\n  }\n\n  type PoolConnection {\n    edges: [PoolEdge!]!\n    pageInfo: PageInfo!\n    totalCount: Int!\n  }\n\n  type PoolEdge {\n    cursor: String!\n    node: Pool!\n  }\n\n  type TransactionConnection {\n    edges: [TransactionEdge!]!\n    pageInfo: PageInfo!\n    totalCount: Int!\n  }\n\n  type TransactionEdge {\n    cursor: String!\n    node: Transaction!\n  }\n\n  type PageInfo {\n    hasNextPage: Boolean!\n    hasPreviousPage: Boolean!\n    startCursor: String\n    endCursor: String\n    total: Int!\n  }\n\n  # Enums\n  enum TokenOrderBy {\n    CREATED_AT_DESC\n    CREATED_AT_ASC\n    MARKET_CAP_DESC\n    VOLUME_DESC\n    HOLDERS_DESC\n  }\n\n  enum LeaderboardType {\n    CREATORS\n    TRADERS\n    LIQUIDITY_PROVIDERS\n    VIRAL_TOKENS\n  }\n\n  enum LeaderboardTimeframe {\n    HOUR\n    DAY\n    WEEK\n    MONTH\n    ALL_TIME\n  }\n\n  enum TransactionType {\n    TOKEN_CREATED\n    TOKEN_BOUGHT\n    TOKEN_SOLD\n    LIQUIDITY_ADDED\n    LIQUIDITY_REMOVED\n    SWAP\n  }\n\n  enum TransactionStatus {\n    PENDING\n    SUCCESS\n    FAILED\n  }\n";
